"""The disclosed exploratory pass (wave7_prereg.md Section 0,
disclosure 1): reproduces the pivot-note calibration statistics on
the two calibration cells under the frozen conventions, in BOTH
variants (warm-up-inclusive, as the pivot note computed them, and
post-warm-up, as the wave-7 gates compute them), and emits them as
TeX macros so every number quoted in the manuscript's exploratory
subsection is script-derived.

Usage: python3 analysis/avalanche_explore.py
Writes docs/figures/w7_explore.tex.  This script reads no gate and
computes no verdict; it is the calibration source the preregistration
discloses.
"""

import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import avalanche as av  # noqa: E402
import gates  # noqa: E402
import thresholds as T  # noqa: E402

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..",
                   "docs", "figures")

FLAT = "w6-base-lr1e-3"
SUBC = "w6-base-lr3e-4"


def stats(warmup):
    tt_f, wu_f, y_f = gates.gnorm_series(FLAT, "plga")
    tt_s, wu_s, y_s = gates.gnorm_series(SUBC, "plga")
    wu = warmup if warmup is not None else 0
    ev_f, _ = av.extract_events(y_f, T.AV_THR_MULT, T.AV_MED_WIN, wu)
    ev_s, _ = av.extract_events(y_s, T.AV_THR_MULT, T.AV_MED_WIN, wu)
    s_f = np.array([e["size"] for e in ev_f])
    s_s = np.array([e["size"] for e in ev_s])
    _, n_dil, n_start = av.exclude_matched(ev_f, ev_s, T.AV_MATCH_LAG)
    out = {
        "FlatN": len(ev_f), "SubN": len(ev_s),
        "FlatSmin": s_f.min(), "FlatSmax": s_f.max(),
        "SubSmax": s_s.max(),
        "FlatSlope": av.ccdf_slope(s_f), "SubSlope": av.ccdf_slope(s_s),
        "FlatCV": av.interevent_cv(ev_f),
        "ExclDil": n_dil, "ExclStart": n_start,
        "DurMax": max(e["dur"] for e in ev_f),
    }
    for blk, tag in (("attn", "Attn"), ("ffn", "Ffn"), ("phi", "Phi")):
        g = gates.gnorm_series(FLAT, blk)
        ev_b, _ = av.extract_events(g[2], T.AV_THR_MULT, T.AV_MED_WIN,
                                    wu)
        c = av.coincidence(ev_f, [e["start"] for e in ev_b], tt_f,
                           T.AV_COINC_LAG)
        out[f"Co{tag}Obs"] = c["observed"]
        out[f"Co{tag}Chance"] = c["chance"]
        out[f"Co{tag}Ratio"] = c["ratio"]
    # the parameter-velocity observable carries no excursions
    rows = sorted((r["step"], r["dtheta_plga"])
                  for r in gates.load_run(FLAT)[1] if "dtheta_plga" in r)
    yd = np.array([v for _, v in rows], float)
    ev_d, _ = av.extract_events(yd, T.AV_THR_MULT, T.AV_MED_WIN, wu)
    out["DthetaN"] = len(ev_d)
    return out


def fmt(k, v):
    if isinstance(v, (int, np.integer)):
        return str(int(v))
    if "Slope" in k or "CV" in k:
        return f"{v:.3f}"
    if "Ratio" in k:
        return f"{v:.2f}"
    if "Obs" in k or "Chance" in k:
        return f"{v:.3f}"
    if "Smin" in k:
        return f"{v:.3g}"
    if "Smax" in k:
        return f"{v:.4g}"
    return f"{v:.3g}"


def main():
    lines = ["% generated by analysis/avalanche_explore.py; the"
             " calibration source disclosed in wave7_prereg.md"]
    for prefix, wu in (("wEx", 0), ("wPw", 1000)):
        s = stats(wu)
        for k, v in s.items():
            lines.append(f"\\gdef\\{prefix}{k}{{{fmt(k, v)}}}")
    path = os.path.join(OUT, "w7_explore.tex")
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")
    print(f"wrote {path} ({len(lines) - 1} macros)")


if __name__ == "__main__":
    main()
